import {test,expect} from '@playwright/test';import {freshState} from '../../src/engine.js';import {videoContent} from '../../src/video-lesson-content.js';
for(const direction of ['ko-ja','ja-ko'])for(const width of [320,390])test(`5-9 subtext investigation ${direction} ${width}`,async({page})=>{
 const id=direction==='ko-ja'?'frieren-subtext':'misaeng-subtext',x=videoContent[id][0];
 await page.setViewportSize({width,height:844});await page.addInitScript(s=>{if(!localStorage.getItem('seodang.web-prototype.v1'))localStorage.setItem('seodang.web-prototype.v1',JSON.stringify(s));localStorage.setItem('seodang.analytics.v1',JSON.stringify({consent:false,queue:[]}));},{...freshState(),onboarded:true,onboardingLevel:7,courseDirection:direction,koreanGuideSeenVersion:1,settings:{sound:false,motion:'off',textScale:1.2,audioRate:1}});
 await page.route('https://www.youtube.com/embed/**',r=>r.fulfill({body:'player fixture'}));
 const enter=()=>page.locator(`.map-choice[data-action="video"][data-id="${id}"]`).click();
 const layout=async()=>{expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1)).toBe(true);const tops=await page.locator('.video-lesson>.button-pair>button').evaluateAll(es=>es.map(e=>e.getBoundingClientRect().top));expect(Math.abs(tops[0]-tops[1])).toBeLessThan(2);};
 await page.goto('/playable.html');await expect(page.locator('.map-choice[data-action]')).toHaveCount(9);await enter();await expect(page.locator('.app-header-title')).toContainText('9.');
 const src=new URL(await page.locator('iframe.lesson-youtube').getAttribute('src'));expect(src.searchParams.get('start')).toBe(String(x.startSeconds));expect(src.searchParams.get('end')).toBe(String(x.endSeconds));expect(src.searchParams.get('cc_load_policy')).toBe('0');
 await expect(page.locator('.video-dialogue')).toBeHidden();await expect(page.locator('.video-detective-result')).toHaveCount(0);await layout();await page.locator('.video-transcript>summary').click();await expect(page.locator('.video-dialogue blockquote')).toHaveText(x.quote);await page.locator('.video-dialogue summary').click();await layout();await page.locator('.video-transcript>summary').click();
 await page.screenshot({path:`output/detective-watch-${direction}-${width}-${test.info().project.name}.png`,fullPage:true});await page.locator('[data-action="video-next"]').click();
 for(const [step,answer] of [['infer',1],['clue',2]]){
  await expect(page.locator(`.video-phase-${step}`)).toBeVisible();await expect(page.locator('[data-action="video-check"]')).toBeDisabled();await layout();
  await page.locator('[data-action="video-select"][data-id="0"]').click();await page.locator('[data-action="video-check"]').click();await expect(page.locator('[role="status"]')).toContainText(x.detective[step==='infer'?'intent':'clue'].hints[0]);await expect(page.locator('.video-detective-feedback')).toBeInViewport();await expect(page.locator('[data-action="video-next"]')).toHaveCount(0);
  if(step==='infer'){await page.reload();await enter();await expect(page.locator('[data-action="video-select"][data-id="0"]')).toHaveAttribute('aria-pressed','true');}
  await page.locator(`[data-action="video-select"][data-id="${answer}"]`).click();await page.locator('[data-action="video-check"]').click();await expect(page.locator('[data-action="video-select"]').first()).toBeDisabled();await expect(page.locator('.video-detective-feedback.success')).toBeInViewport();await expect(page.locator('[data-action="video-select"].correct')).toHaveCount(1);await layout();await page.screenshot({path:`output/detective-${step}-${direction}-${width}-${test.info().project.name}.png`,fullPage:true});if(step==='clue'){await page.locator('[data-action="video-replay"]').click();await expect(page.locator('.video-phase-watch')).toBeVisible();await layout();await page.locator('[data-action="video-next"]').click();await expect(page.locator('.video-phase-clue')).toBeVisible();await expect(page.locator(`[data-action="video-select"][data-id="${answer}"]`)).toHaveClass(/correct/);}await page.locator('[data-action="video-next"]').click();
 }
 await expect(page.locator('.video-detective-result')).toBeVisible();await expect(page.locator('.video-lesson')).toHaveAttribute('lang',direction==='ko-ja'?'ko':'ja');await layout();await page.screenshot({path:`output/detective-result-${direction}-${width}-${test.info().project.name}.png`,fullPage:true});await page.locator('[data-action="video-next"]').click();await expect(page.locator('.practice-fireworks svg')).toBeVisible();await page.locator('[data-action="completed-next"]').click();await page.reload();await expect(page.locator(`.map-choice[data-id="${id}"]`)).toContainText(direction==='ko-ja'?'완료':'完了');
});
for(const direction of ['ko-ja','ja-ko'])test(`5-9 native player uses exact bounds and leaves before inference ${direction}`,async({page})=>{
 const id=direction==='ko-ja'?'frieren-subtext':'misaeng-subtext',line=videoContent[id][0];
 await page.addInitScript(s=>{localStorage.setItem('seodang.web-prototype.v1',JSON.stringify(s));localStorage.setItem('seodang.analytics.v1',JSON.stringify({consent:false,queue:[]}));window.videoCalls=[];window.Capacitor={getPlatform:()=> 'ios',isNativePlatform:()=>true,isPluginAvailable:name=>name==='SeodangVideo',nativePromise:async(plugin,method,args)=>{if(plugin==='SeodangVideo')window.videoCalls.push({method,args});return {};}};},{...freshState(),onboarded:true,onboardingLevel:7,courseDirection:direction,koreanGuideSeenVersion:1,settings:{sound:false,motion:'off',textScale:1,audioRate:1}});
 await page.goto('/playable.html');await page.locator(`.map-choice[data-id="${id}"]`).click();await expect(page.locator('[data-native-video]')).toBeVisible();await expect.poll(()=>page.evaluate(()=>window.videoCalls.find(c=>c.method==='mount')?.args.videoId)).toBe(line.videoId);
 const mount=await page.evaluate(()=>window.videoCalls.find(c=>c.method==='mount'));expect(mount.args.startSeconds).toBe(line.startSeconds);expect(mount.args.endSeconds).toBe(line.endSeconds);
 await page.locator('[data-action="video-next"]').click();await expect(page.locator('.video-phase-infer')).toBeVisible();await expect.poll(()=>page.evaluate(()=>window.videoCalls.at(-1).method)).toBe('remove');await page.locator('[data-action="video-replay"]').click();await expect.poll(()=>page.evaluate(()=>window.videoCalls.filter(c=>c.method==='mount').length)).toBe(2);
});
